/* Local, dependency-free ROF12 HTMX subset: GET swaps for dashboard partials. */
(()=>{const load=async e=>{const el=e.target.closest("[hx-get]");if(!el)return;const target=document.querySelector(el.getAttribute("hx-target"));if(!target)return;const r=await fetch(el.getAttribute("hx-get"),{headers:{"X-Requested-With":"XMLHttpRequest"}});if(r.ok)target.innerHTML=await r.text()};document.addEventListener("click",load)})();
